contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address caller, uint256 value) public {
        require(caller != address(0));
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 callerBalanceBefore = c.balanceOf(caller); if (__ESBMC_reverted()) return;

        c.burn(value); if (__ESBMC_reverted()) return;

        assert(c.totalSupply() == supplyBefore && c.balanceOf(caller) == callerBalanceBefore);
    }
}

