pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address caller, uint256 value) internal {
        vm.assume(caller != address(0));
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 callerBalanceBefore;
        try c.balanceOf(caller) returns (uint256 __r) { callerBalanceBefore = __r; } catch { return; }
        try c.burn(value) {} catch { return; }
        assertTrue(c.totalSupply() == supplyBefore && c.balanceOf(caller) == callerBalanceBefore);
    }

